import { AsyncLocalStorage } from 'node:async_hooks';
export type HistoryEntry = { name: string; at: string };
export const hopStore = new AsyncLocalStorage<HistoryEntry[]>();

export function withHop<T>(name: string, fn: () => Promise<T>): Promise<T> {
  const hops = [...(hopStore.getStore() ?? []), { name, at: new Date().toISOString() }];
  return hopStore.run(hops, fn);   // in-process hops; serialize into headers at the edge
}
